<body>
<div id="app">
  <header>
    <h1>双摆物理仿真 <small>Double Pendulum · 固定步长 RK4 积分</small></h1>
    <div class="badges">
      <div class="badge">轨迹 <b id="trailCount">0</b></div>
      <div class="badge">模拟时间 <b id="simTimeBadge">0.000 s</b></div>
