  #app{display:flex;flex-direction:column;height:100vh;max-height:100vh}
  header{
    display:flex;align-items:center;gap:14px;flex-wrap:wrap;
    padding:9px 16px;border-bottom:1px solid var(--line);
    background:rgba(13,20,29,.82);backdrop-filter:blur(8px);
  }
  header h1{font-size:17px;margin:0;letter-spacing:.04em;font-weight:600;white-space:nowrap}
  header h1 small{color:var(--muted);font-weight:400;margin-left:8px;font-size:12px}
  .badges{margin-left:auto;display:flex;gap:8px;flex-wrap:wrap}
  .badge{
    font-size:11px;color:var(--muted);border:1px solid var(--line);
    padding:4px 8px;border-radius:999px;background:var(--panel-2)
  }
  .badge b{color:var(--text);font-weight:600}
  main{flex:1;display:flex;gap:12px;padding:12px;min-height:0}
  .stage{flex:1;display:flex;flex-direction:column;gap:10px;min-width:0}
  .canvas-card{
    position:relative;flex:1;min-height:0;background:var(--panel-2);
    border:1px solid var(--line);border-radius:14px;overflow:hidden;box-shadow:var(--shadow)
  }
  canvas#sim{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none;cursor:grab}
  canvas#sim.dragging{cursor:grabbing}
  .hud{
    position:absolute;left:10px;top:10px;right:10px;display:flex;gap:8px;flex-wrap:wrap;
    pointer-events:none;z-index:3
  }
  .hud .chip{
    background:rgba(8,12,18,.72);border:1px solid var(--line);border-radius:8px;
    padding:6px 9px;font-size:12px;backdrop-filter:blur(6px);min-width:104px
  }
  .hud .chip span{display:block;color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.08em}
  .hud .chip b{font-size:13px;font-weight:650}
  .hud .chip.energy b{color:var(--cyan)}
  .hud .chip.error b{color:var(--amber)}
  .paused-badge{
    position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);
    background:rgba(8,12,18,.68);border:1px solid var(--line);color:var(--amber);
    padding:8px 18px;border-radius:999px;font-size:13px;letter-spacing:.3em;
    pointer-events:none;display:none;z-index:4
  }
  .readout-row{display:flex;gap:10px;flex-wrap:wrap}
  .metric{
    flex:1;min-width:190px;background:var(--panel);border:1px solid var(--line);
    border-radius:12px;padding:9px 12px;box-shadow:var(--shadow)
  }
  .metric label{display:flex;justify-content:space-between;color:var(--muted);font-size:11px;letter-spacing:.06em;text-transform:uppercase}
  .metric .value{font-size:19px;font-weight:700;margin-top:3px;font-variant-numeric:tabular-nums}
  .metric .sub{font-size:11px;color:var(--muted);margin-top:2px;font-variant-numeric:tabular-nums}
  .metric.good .value{color:var(--green)}
  .metric.warn .value{color:var(--amber)}
  .metric.bad .value{color:var(--red)}
  .chart-card{flex:1.25;min-width:260px;background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:8px 10px;box-shadow:var(--shadow)}
  .chart-card .chart-title{display:flex;justify-content:space-between;font-size:11px;color:var(--muted);letter-spacing:.06em;text-transform:uppercase}
  canvas#driftChart{width:100%;height:82px;display:block}
  aside{
    width:330px;min-width:330px;background:var(--panel);border:1px solid var(--line);
    border-radius:14px;padding:12px;overflow:auto;box-shadow:var(--shadow)
  }
  aside h2{font-size:13px;margin:0 0 10px;color:var(--text);display:flex;align-items:center;gap:8px}
  aside h2::before{content:"";width:8px;height:8px;border-radius:2px;background:linear-gradient(135deg,var(--cyan),var(--pink))}
  .group{border-top:1px solid var(--line);padding:10px 0}
  .group:first-of-type{border-top:0;padding-top:0}
  .group h3{font-size:11px;margin:0 0 8px;color:var(--muted);letter-spacing:.09em;text-transform:uppercase;font-weight:600}
  .control{margin:7px 0}
  .control label{display:flex;justify-content:space-between;gap:8px;font-size:12px;color:#c6d4df;margin-bottom:5px}
  .control output{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;color:var(--cyan);font-size:12px;white-space:nowrap}
  input[type="range"]{
    -webkit-appearance:none;appearance:none;width:100%;height:5px;border-radius:5px;
    background:linear-gradient(90deg,var(--cyan),var(--pink));outline:none;cursor:pointer
  }
  input[type="range"]::-webkit-slider-thumb{
    -webkit-appearance:none;appearance:none;width:17px;height:17px;border-radius:50%;
    background:#fff;border:3px solid var(--cyan);box-shadow:0 0 8px rgba(53,208,255,.6);cursor:grab
  }
  input[type="range"]::-moz-range-thumb{
    width:15px;height:15px;border-radius:50%;background:#fff;border:3px solid var(--cyan);cursor:grab
  }
  .btn-row{display:flex;gap:8px;flex-wrap:wrap;margin-top:4px}
  button{
    flex:1;min-width:88px;border-radius:10px;border:1px solid var(--line);
    background:#172331;color:var(--text);padding:9px 10px;font-size:13px;cursor:pointer;
    transition:background .15s,border-color .15s,transform .1s
  }
  button:hover{background:#1e3040;border-color:#365063}
  button:active{transform:translateY(1px)}
  button.primary{background:linear-gradient(135deg,#0b7aa5,#164e78);border-color:#1d7fa3}
  button.primary:hover{background:linear-gradient(135deg,#0e8fc2,#1c6397)}
  button#pauseBtn.paused{background:#4a3515;border-color:#8a6420;color:var(--amber)}
  .hint{font-size:11px;line-height:1.55;color:var(--muted);padding:8px 0 2px}
  .hint b{color:#bdd4e6;font-weight:600}
  footer{padding:0 12px 8px;font-size:10px;color:#53677a;text-align:center}
  @media (max-width:980px){
    body{overflow:auto}
    #app{height:auto;min-height:100vh}
    main{flex-direction:column;overflow:visible}
    aside{width:100%;min-width:0}
    .canvas-card{min-height:420px;height:460px}
  }
</style>
</head>
<body>
<div id="app">
  <header>
    <h1>双摆物理仿真 <small>Double Pendulum · 固定步长 RK4 积分</small></h1>
    <div class="badges">
      <div class="badge">轨迹 <b id="trailCount">0</b></div>
      <div class="badge">模拟时间 <b id="simTimeBadge">0.000 s</b></div>
      <div class="badge">积分步数 <b id="stepCount">0</b></div>
    </div>
  </header>

  <main>
    <section class="stage">
      <div class="canvas-card">
        <canvas id="sim" aria-label="双摆轨迹画布"></canvas>
        <div class="hud">
          <div class="chip energy"><span>Total energy · 总能量</span><b id="energyHud">--</b></div>
          <div class="chip error"><span>Relative energy error · 相对能量误差</span><b id="errorHud">--</b></div>
          <div class="chip"><span>Trajectory · 轨迹</span><b id="trajectoryHud">trail on</b></div>
        </div>
        <div class="paused-badge" id="pausedBadge">已暂停 PAUSED</div>
      </div>

      <div class="readout-row">
        <div class="metric good" id="energyMetric">
          <label><span>Total energy 总能量</span><span id="energyState">--</span></label>
          <div class="value" id="energyValue">-- J</div>
          <div class="sub">Baseline E₀ <span id="baselineValue">-- J</span> · after parameter changes, E₀ is re-captured</div>
        </div>
        <div class="metric good" id="errorMetric">
          <label><span>Relative energy error 相对能量误差</span><span>RK4 drift</span></label>
          <div class="value" id="errorValue">0.000000%</div>
          <div class="sub">Peak absolute <span id="peakErrorValue">0.000000%</span> · |E/E₀ − 1|</div>
        </div>
        <div class="chart-card">
          <div class="chart-title"><span>Energy drift history 能量漂移历史</span><span id="chartRange">auto</span></div>
          <canvas id="driftChart" aria-label="能量误差历史图"></canvas>
        </div>
      </div>
    </section>

    <aside>
      <h2>Parameters · 可调参数</h2>

      <div class="group">
        <h3>Physical parameters 物理参数</h3>
        <div class="control">
          <label for="gSlider">重力加速度 g <output id="gOut">9.81 m/s²</output></label>
          <input id="gSlider" type="range" min="0.5" max="24" step="0.01" value="9.81">
        </div>
        <div class="control">
          <label for="m1Slider">质量 m₁ <output id="m1Out">1.20 kg</output></label>
          <input id="m1Slider" type="range" min="0.2" max="6" step="0.05" value="1.2">
        </div>
        <div class="control">
          <label for="m2Slider">质量 m₂ <output id="m2Out">0.90 kg</output></label>
          <input id="m2Slider" type="range" min="0.2" max="6" step="0.05" value="0.9">
        </div>
        <div class="control">
          <label for="l1Slider">摆长 L₁ <output id="l1Out">1.50 m</output></label>
          <input id="l1Slider" type="range" min="0.3" max="2.6" step="0.01" value="1.5">
        </div>
        <div class="control">
          <label for="l2Slider">摆长 L₂ <output id="l2Out">1.20 m</output></label>
          <input id="l2Slider" type="range" min="0.3" max="2.6" step="0.01" value="1.2">
        </div>
      </div>

      <div class="group">
        <h3>Initial pose 初始角度（Reset 后生效）</h3>
        <div class="control">
          <label for="th1Slider">θ₁ <output id="th1Out">120.0°</output></label>
          <input id="th1Slider" type="range" min="-180" max="180" step="0.5" value="120">
        </div>
        <div class="control">
          <label for="th2Slider">θ₂ <output id="th2Out">143.0°</output></label>
          <input id="th2Slider" type="range" min="-180" max="180" step="0.5" value="143">
        </div>
      </div>

      <div class="group">
        <h3>Numerics 数值 / 速度</h3>
        <div class="control">
          <label for="dtSlider">RK4 步长 dt <output id="dtOut">0.40 ms</output></label>
          <input id="dtSlider" type="range" min="0.0001" max="0.002" step="0.00005" value="0.0004">
        </div>
        <div class="control">
          <label for="speedSlider">模拟速度 <output id="speedOut">1.00 ×</output></label>
          <input id="speedSlider" type="range" min="0.1" max="2" step="0.05" value="1">
        </div>
        <div class="control">
          <label for="trailSlider">Trajectory 轨迹长度 <output id="trailOut">1600</output></label>
          <input id="trailSlider" type="range" min="0" max="5000" step="100" value="1600">
        </div>
        <div class="control">
          <label for="gridToggle">显示网格 / 参考圆 <output id="gridOut">on</output></label>
          <input id="gridToggle" type="range" min="0" max="1" step="1" value="1">
        </div>
      </div>

      <div class="btn-row">
        <button id="pauseBtn" class="primary" type="button">Pause 暂停</button>
        <button id="resetBtn" type="button">Reset 重置</button>
        <button id="clearBtn" type="button">Clear trail 清轨迹</button>
      </div>

      <div class="hint">
        <b>交互：</b>拖动滑块实时改变物理参数；也可直接用鼠标/手指抓住任一个摆球拖动，速度会归零。
        能量误差为 <b>|E/E₀ − 1|</b>，RK4 固定步长下应保持在很低水平。初始值可稳定仿真 60 秒以上。
      </div>
      <div class="hint" id="selfTestHint">页面已运行 DOM 自检：<span id="selfTestBadge">waiting</span></div>
    </aside>
  </main>
  <footer>单文件离线仿真 · HTML + CSS + JavaScript 内嵌 · 无外部依赖</footer>
</div>

<script>
(function(){
  "use strict";

  /* ---------- DOM shortcuts ---------- */
  const $ = function(id){ return document.getElementById(id); };
  const sim = $("sim"), simCtx = sim.getContext("2d");
  const driftCanvas = $("driftChart"), driftCtx = driftCanvas.getContext("2d");
  const ui = {
    g: $("gSlider"), m1: $("m1Slider"), m2: $("m2Slider"),
    l1: $("l1Slider"), l2: $("l2Slider"),
    th1: $("th1Slider"), th2: $("th2Slider"),
    dt: $("dtSlider"), speed: $("speedSlider"), trailLen: $("trailSlider"), grid: $("gridToggle"),
    gOut: $("gOut"), m1Out: $("m1Out"), m2Out: $("m2Out"),
    l1Out: $("l1Out"), l2Out: $("l2Out"),
    th1Out: $("th1Out"), th2Out: $("th2Out"),
    dtOut: $("dtOut"), speedOut: $("speedOut"), trailOut: $("trailOut"), gridOut: $("gridOut"),
    energyHud: $("energyHud"), errorHud: $("errorHud"), trajectoryHud: $("trajectoryHud"),
    energyValue: $("energyValue"), baselineValue: $("baselineValue"),
    errorValue: $("errorValue"), peakErrorValue: $("peakErrorValue"),
    energyState: $("energyState"), energyMetric: $("energyMetric"), errorMetric: $("errorMetric"),
    pauseBtn: $("pauseBtn"), resetBtn: $("resetBtn"), clearBtn: $("clearBtn"),
    pausedBadge: $("pausedBadge"), trailCount: $("trailCount"),
    simTimeBadge: $("simTimeBadge"), stepCount: $("stepCount"),
    chartRange: $("chartRange"), selfTestBadge: $("selfTestBadge")
  };

  const TAU = Math.PI * 2;
  const DEG = Math.PI / 180;

  const P = {
    g: 9.81, m1: 1.2, m2: 0.9, l1: 1.5, l2: 1.2,
    dt: 0.0004, speed: 1.0, trailLen: 1600, grid: true,
    th1: 120 * DEG, th2: 143 * DEG,
    running: true, simTime: 0, steps: 0, E0: null,
    energy: 0, error: 0, peakError: 0, maxSeenError: 0,
    trail: [], trailSampleAcc: 0, sampleInterval: 1/160,
    errorHistory: [], errorSampleAcc: 0, errorSampleInterval: 0.08,
    lastFrame: performance.now(), lastDragWasPointer: false
  };

  /* y = [theta1, omega1, theta2, omega2] */
  let y = [P.th1, 0, P.th2, 0];

  /* ---------- Equations of motion (double pendulum, y axis points down) ---------- */
  function derivs(s){
    var d = s[0] - s[2];
    var cd = Math.cos(d), sd = Math.sin(d);
    var s1 = Math.sin(s[0]), s2 = Math.sin(s[2]);
    var den = 2*P.m1 + P.m2 - P.m2*Math.cos(2*d);
    var a1 = (-P.g*(2*P.m1 + P.m2)*s1
              - P.m2*P.g*Math.sin(s[0] - 2*s[2])
              - 2*sd*P.m2*(s[3]*s[3]*P.l2 + s[1]*s[1]*P.l1*cd)
             ) / (P.l1*den);
    var a2 = (2*sd*(s[1]*s[1]*P.l1*(P.m1 + P.m2)
                    + P.g*(P.m1 + P.m2)*Math.cos(s[0])
                    + s[3]*s[3]*P.l2*P.m2*cd)
             ) / (P.l2*den);
    return [s[1], a1, s[3], a2];
  }

  /* Classical fixed-step Runge-Kutta 4 integrator */
  function rk4Step(state, dt){
    var k1 = derivs(state);
    var s2 = [state[0] + dt*0.5*k1[0], state[1] + dt*0.5*k1[1],
              state[2] + dt*0.5*k1[2], state[3] + dt*0.5*k1[3]];
    var k2 = derivs(s2);
    var s3 = [state[0] + dt*0.5*k2[0], state[1] + dt*0.5*k2[1],
              state[2] + dt*0.5*k2[2], state[3] + dt*0.5*k2[3]];
    var k3 = derivs(s3);
    var s4 = [state[0] + dt*k3[0], state[1] + dt*k3[1],
              state[2] + dt*k3[2], state[3] + dt*k3[3]];
    var k4 = derivs(s4);
    return [state[0] + dt/6*(k1[0] + 2*k2[0] + 2*k3[0] + k4[0]),
            state[1] + dt/6*(k1[1] + 2*k2[1] + 2*k3[1] + k4[1]),
            state[2] + dt/6*(k1[2] + 2*k2[2] + 2*k3[2] + k4[2]),
            state[3] + dt/6*(k1[3] + 2*k2[3] + 2*k3[3] + k4[3])];
  }

  /* Energy: kinetic (both bobs) + gravitational potential (pivot is zero level). */
  function totalEnergy(s){
    var t1 = s[0], w1 = s[1], t2 = s[2], w2 = s[3];
    var T = 0.5*P.m1*P.l1*P.l1*w1*w1
          + 0.5*P.m2*(P.l1*P.l1*w1*w1 + P.l2*P.l2*w2*w2
                      + 2*P.l1*P.l2*w1*w2*Math.cos(t1 - t2));
    var V = -(P.m1 + P.m2)*P.g*P.l1*Math.cos(t1)
            - P.m2*P.g*P.l2*Math.cos(t2);
    return T + V;
  }

  function captureBaseline(){
    P.E0 = totalEnergy(y);
    P.energy = P.E0;
    P.error = 0;
    P.peakError = 0;
    P.errorHistory.length = 0;
  }

  function bobPositions(s){
    var x1 = P.l1*Math.sin(s[0]), y1 = P.l1*Math.cos(s[0]);
    var x2 = x1 + P.l2*Math.sin(s[2]), y2 = y1 + P.l2*Math.cos(s[2]);
    return {x1:x1, y1:y1, x2:x2, y2:y2};
  }

  function currentBobPositions(){ return bobPositions(y); }

  /* ---------- State transitions ---------- */
  function resetState(){
    y = [P.th1, 0, P.th2, 0];
    P.simTime = 0; P.steps = 0;
    P.trail.length = 0; P.trailSampleAcc = 0;
    P.errorHistory.length = 0; P.errorSampleAcc = 0;
    captureBaseline();
    syncInputs();
    updateReadouts(true);
  }

  function setRunning(running){
    P.running = !!running;
    if(P.running){
      P.lastFrame = performance.now();
      ui.pauseBtn.textContent = "Pause 暂停";
      ui.pauseBtn.classList.remove("paused");
      ui.pausedBadge.style.display = "none";
    }else{
      ui.pauseBtn.textContent = "Resume 继续";
      ui.pauseBtn.classList.add("paused");
      ui.pausedBadge.style.display = "block";
    }
  }

  function clearTrail(){
    P.trail.length = 0;
    P.errorHistory.length = 0;
    P.peakError = 0;
  }

  /* Called when a live physical parameter changes: re-capture baseline so the
     energy-error indicator measures drift from the new configuration onward. */
  function physicalParameterChanged(){
    P.trail.length = 0;
    P.errorHistory.length = 0;
    P.peakError = 0;
    captureBaseline();
    updateReadouts(true);
  }

  /* ---------- UI wiring ---------- */
  function fmt(n, digits){
    if(!isFinite(n)) return "∞";
    if(digits === undefined) digits = 2;
    return n.toFixed(digits);
  }
  function fmtSci(n, digits){
    if(!isFinite(n)) return "∞";
    if(n === 0) return "0";
    var a = Math.abs(n);
    if(a >= 1000 || a < 0.001) return n.toExponential(digits || 2);
    return n.toFixed(digits || 4);
  }

  function syncInputs(){
    ui.g.value = P.g; ui.gOut.textContent = fmt(P.g,2) + " m/s²";
    ui.m1.value = P.m1; ui.m1Out.textContent = fmt(P.m1,2) + " kg";
    ui.m2.value = P.m2; ui.m2Out.textContent = fmt(P.m2,2) + " kg";
    ui.l1.value = P.l1; ui.l1Out.textContent = fmt(P.l1,2) + " m";
    ui.l2.value = P.l2; ui.l2Out.textContent = fmt(P.l2,2) + " m";
    ui.th1.value = P.th1/DEG; ui.th1Out.textContent = fmt(P.th1/DEG,1) + "°";
    ui.th2.value = P.th2/DEG; ui.th2Out.textContent = fmt(P.th2/DEG,1) + "°";
    ui.dt.value = P.dt; ui.dtOut.textContent = fmt(P.dt*1000,2) + " ms";
    ui.speed.value = P.speed; ui.speedOut.textContent = fmt(P.speed,2) + " ×";
    ui.trailLen.value = P.trailLen; ui.trailOut.textContent = P.trailLen;
    ui.grid.value = P.grid ? 1 : 0; ui.gridOut.textContent = P.grid ? "on" : "off";
  }

  function updateReadouts(force){
    var errPct = P.error;
    ui.energyHud.textContent = fmtSci(P.energy,4) + " J";
    ui.errorHud.textContent = (errPct >= 0 ? "+" : "") + errPct.toFixed(6) + "%";
    ui.trajectoryHud.textContent = P.trailLen > 0 ? "trail on" : "trail off";
    ui.energyValue.textContent = fmtSci(P.energy,4) + " J";
    ui.baselineValue.textContent = fmtSci(P.E0,4) + " J";
    ui.errorValue.textContent = (errPct >= 0 ? "+" : "") + errPct.toFixed(6) + "%";
    ui.peakErrorValue.textContent = fmt(P.peakError,6) + "%";
    ui.energyState.textContent = "conserved";
    ui.trailCount.textContent = String(P.trail.length);
    ui.simTimeBadge.textContent = fmt(P.simTime,3) + " s";
    ui.stepCount.textContent = String(P.steps);

    var a = Math.abs(errPct);
    var metricCls = a < 0.05 ? "good" : (a < 0.5 ? "warn" : "bad");
    ui.errorMetric.className = "metric " + metricCls;
    ui.energyMetric.className = "metric " + (a < 0.05 ? "good" : (a < 0.5 ? "warn" : "bad"));
  }

  ui.g.addEventListener("input", function(){ P.g = parseFloat(this.value); physicalParameterChanged(); });
  ui.m1.addEventListener("input", function(){ P.m1 = parseFloat(this.value); physicalParameterChanged(); });
  ui.m2.addEventListener("input", function(){ P.m2 = parseFloat(this.value); physicalParameterChanged(); });
  ui.l1.addEventListener("input", function(){ P.l1 = parseFloat(this.value); physicalParameterChanged(); });
  ui.l2.addEventListener("input", function(){ P.l2 = parseFloat(this.value); physicalParameterChanged(); });
  ui.th1.addEventListener("input", function(){
    P.th1 = parseFloat(this.value)*DEG;
    ui.th1Out.textContent = fmt(parseFloat(this.value),1) + "°";
  });
  ui.th2.addEventListener("input", function(){
    P.th2 = parseFloat(this.value)*DEG;
    ui.th2Out.textContent = fmt(parseFloat(this.value),1) + "°";
  });
  ui.dt.addEventListener("input", function(){
    P.dt = parseFloat(this.value);
    ui.dtOut.textContent = fmt(P.dt*1000,2) + " ms";
  });
  ui.speed.addEventListener("input", function(){
    P.speed = parseFloat(this.value);
    ui.speedOut.textContent = fmt(P.speed,2) + " ×";
  });
  ui.trailLen.addEventListener("input", function(){
    P.trailLen = parseInt(this.value,10);
    ui.trailOut.textContent = P.trailLen;
    if(P.trail.length > P.trailLen) P.trail.length = P.trailLen;
  });
  ui.grid.addEventListener("input", function(){
    P.grid = this.value === "1";
    ui.gridOut.textContent = P.grid ? "on" : "off";
  });
  ui.pauseBtn.addEventListener("click", function(){ setRunning(!P.running); });
  ui.resetBtn.addEventListener("click", resetState);
  ui.clearBtn.addEventListener("click", clearTrail);
  window.addEventListener("keydown", function(e){
    if(e.code === "Space" && e.target.tagName !== "INPUT" && e.target.tagName !== "BUTTON"){
      e.preventDefault();
      setRunning(!P.running);
    }
  });

  /* ---------- Direct dragging of bobs ---------- */
  function screenToWorld(px, py, view){
    return {
      x: (px - view.cx)/view.scale,
      y: (py - view.pivotY)/view.scale
    };
  }
  function getView(w, h){
    var maxArm = P.l1 + P.l2;
    var pivotY = Math.max(72, h*0.16);
    var scale = Math.min((w*0.5 - 48)/maxArm, (h - pivotY - 58)/maxArm);
    scale = Math.max(12, scale);
    return {cx:w*0.5, pivotY:pivotY, scale:scale};
  }
  function hitTest(px, py, view){
    var p = currentBobPositions();
    var x1 = view.cx + p.x1*view.scale, y1 = view.pivotY + p.y1*view.scale;
    var x2 = view.cx + p.x2*view.scale, y2 = view.pivotY + p.y2*view.scale;
    var r1 = bobRadius(P.m1), r2 = bobRadius(P.m2);
    if((px-x2)*(px-x2) + (py-y2)*(py-y2) <= (r2+12)*(r2+12)) return {bob:2, x:x2, y:y2};
    if((px-x1)*(px-x1) + (py-y1)*(py-y1) <= (r1+12)*(r1+12)) return {bob:1, x:x1, y:y1};
    return null;
  }
  function bobRadius(m){
    return Math.max(9, Math.min(17, 9 + 5*Math.cbrt(m)));
  }

  let drag = null;
  function canvasPos(e){
    var r = sim.getBoundingClientRect();
    return {x: e.clientX - r.left, y: e.clientY - r.top};
  }
  sim.addEventListener("pointerdown", function(e){
    var pos = canvasPos(e);
    var view = getView(sim.clientWidth, sim.clientHeight);
    var hit = hitTest(pos.x, pos.y, view);
    if(!hit) return;
    sim.setPointerCapture(e.pointerId);
    drag = {id:e.pointerId, bob:hit.bob};
    sim.classList.add("dragging");
    e.preventDefault();
  });
  sim.addEventListener("pointermove", function(e){
    if(!drag || drag.id !== e.pointerId) return;
    var pos = canvasPos(e);
    var view = getView(sim.clientWidth, sim.clientHeight);
    var w = screenToWorld(pos.x, pos.y, view);
    if(drag.bob === 1){
      y[0] = Math.atan2(w.x, w.y);
    }else{
      var p = currentBobPositions();
      var dx = w.x - p.x1, dy = w.y - p.y1;
      if(dx*dx + dy*dy > 0.0001) y[2] = Math.atan2(dx, dy);
    }
    y[1] = 0; y[3] = 0;
    P.trail.length = 0;
    captureBaseline();
    updateReadouts(true);
    e.preventDefault();
  });
  sim.addEventListener("pointerup", function(e){
    if(drag && drag.id === e.pointerId){
      drag = null;
      sim.classList.remove("dragging");
      try{ sim.releasePointerCapture(e.pointerId); }catch(err){}
    }
  });
  sim.addEventListener("pointercancel", function(e){
    if(drag && drag.id === e.pointerId){
      drag = null;
      sim.classList.remove("dragging");
      try{ sim.releasePointerCapture(e.pointerId); }catch(err){}
    }
  });

  /* ---------- Trajectory and error history sampling ---------- */
  function sampleTrajectory(s){
    var p = bobPositions(s);
    P.trail.push({t:P.simTime, x1:p.x1, y1:p.y1, x2:p.x2, y2:p.y2});
    if(P.trail.length > P.trailLen) P.trail.splice(0, P.trail.length - P.trailLen);
  }
  function sampleError(){
    P.errorHistory.push({t:P.simTime, e:P.error});
    var maxLen = Math.max(120, Math.min(2000, P.trailLen || 2000));
    if(P.errorHistory.length > maxLen) P.errorHistory.splice(0, P.errorHistory.length - maxLen);
  }

  /* ---------- Main fixed-timestep loop ---------- */
  function advanceSimulation(realSeconds){
    var remaining = realSeconds * P.speed;
    var guard = 0;
    while(remaining > 1e-12 && guard < 100000){
      guard++;
      var h = Math.min(P.dt, remaining);
      y = rk4Step(y, h);
      P.simTime += h;
      P.steps += 1;
      remaining -= h;

      P.trailSampleAcc += h;
      if(P.trailLen > 0 && P.trailSampleAcc >= P.sampleInterval){
        sampleTrajectory(y);
        P.trailSampleAcc = 0;
      }
      P.errorSampleAcc += h;
      if(P.errorSampleAcc >= P.errorSampleInterval){
        P.error = computeError();
        sampleError();
        P.errorSampleAcc = 0;
      }
    }
    if(guard >= 100000){
      /* Very large elapsed time: drop the unprocessed tail instead of blocking the UI. */
      P.lastFrame = performance.now();
    }
  }

  function computeError(){
    P.energy = totalEnergy(y);
    var denom = Math.abs(P.E0);
    var err;
    if(denom > 1e-12) err = (P.energy - P.E0)/denom*100;
    else err = P.energy - P.E0;
    P.error = err;
    var a = Math.abs(err);
    if(a > P.peakError) P.peakError = a;
    return err;
  }

  function frame(now){
    var real = Math.min(0.05, Math.max(0, (now - P.lastFrame)/1000));
    P.lastFrame = now;
    if(P.running){
      advanceSimulation(real);
      P.error = computeError();
    }
    drawScene();
    drawDriftChart();
    updateReadouts(false);
    requestAnimationFrame(frame);
  }

  /* ---------- Canvas drawing ---------- */
  function setupCanvas(canvas, ctx){
    var dpr = window.devicePixelRatio || 1;
    var w = canvas.clientWidth, h = canvas.clientHeight;
    if(w === 0 || h === 0) return false;
    var bw = Math.round(w*dpr), bh = Math.round(h*dpr);
    if(canvas.width !== bw || canvas.height !== bh){
      canvas.width = bw; canvas.height = bh;
    }
    ctx.setTransform(dpr,0,0,dpr,0,0);
    return true;
  }

  function drawScene(){
    var w = sim.clientWidth, h = sim.clientHeight;
    if(!setupCanvas(sim, simCtx) || w < 20 || h < 20) return;
    simCtx.clearRect(0,0,w,h);

    var view = getView(w,h);
    var cx = view.cx, pivotY = view.pivotY, scale = view.scale;

    if(P.grid){
      simCtx.save();
      simCtx.strokeStyle = "rgba(90,125,155,.11)";
      simCtx.lineWidth = 1;
      simCtx.beginPath();
      var step = 1;
      if(scale < 45) step = 2;
      if(scale < 22) step = 4;
      for(var x = -8; x <= 8; x += step){
        var sx = cx + x*scale;
        simCtx.moveTo(sx, 0); simCtx.lineTo(sx, h);
      }
      for(var yv = -8; yv <= 8; yv += step){
        var sy = pivotY + yv*scale;
        simCtx.moveTo(0, sy); simCtx.lineTo(w, sy);
      }
      simCtx.stroke();
      /* faint reachability circles */
      simCtx.strokeStyle = "rgba(53,208,255,.10)";
      simCtx.beginPath(); simCtx.arc(cx, pivotY, scale*(P.l1 + P.l2), 0, TAU); simCtx.stroke();
      simCtx.strokeStyle = "rgba(255,79,163,.08)";
      simCtx.beginPath(); simCtx.arc(cx, pivotY, scale*Math.abs(P.l1 - P.l2), 0, TAU); simCtx.stroke();
      simCtx.restore();
    }

    /* Trajectory trails */
    if(P.trail.length > 1){
      drawTrail(P.trail, cx, pivotY, scale, "x1","y1", "rgba(53,208,255,", "cyan");
      drawTrail(P.trail, cx, pivotY, scale, "x2","y2", "rgba(255,79,163,", "magenta");
    }

    var p = currentBobPositions();
    var sx1 = cx + p.x1*scale, sy1 = pivotY + p.y1*scale;
    var sx2 = cx + p.x2*scale, sy2 = pivotY + p.y2*scale;

    /* pivot */
    simCtx.save();
    simCtx.fillStyle = "#dfe8f0";
    simCtx.beginPath(); simCtx.arc(cx, pivotY, 6, 0, TAU); simCtx.fill();
    simCtx.strokeStyle = "#51677a"; simCtx.lineWidth = 2;
    simCtx.beginPath(); simCtx.moveTo(cx, pivotY); simCtx.lineTo(cx, pivotY + 18); simCtx.stroke();

    /* rods */
    simCtx.lineCap = "round";
    simCtx.strokeStyle = "rgba(190,213,230,.85)";
    simCtx.lineWidth = Math.max(3, 0.07*scale*0.22);
    simCtx.beginPath(); simCtx.moveTo(cx, pivotY); simCtx.lineTo(sx1, sy1); simCtx.stroke();
    simCtx.strokeStyle = "rgba(255,180,210,.85)";
    simCtx.beginPath(); simCtx.moveTo(sx1, sy1); simCtx.lineTo(sx2, sy2); simCtx.stroke();

    drawBob(sx1, sy1, bobRadius(P.m1), "#35d0ff", "#063546");
    drawBob(sx2, sy2, bobRadius(P.m2), "#ff4fa3", "#4a0825");
    simCtx.restore();
  }

  function drawTrail(arr, cx, pivotY, scale, kx, ky, baseColor, label){
    var n = arr.length;
    simCtx.save();
    simCtx.lineCap = "round";
    simCtx.lineJoin = "round";
    /* older points are drawn first with low alpha */
    var segment = Math.max(1, Math.floor(n/110));
    for(var i = 0; i < n - 1; i += segment){
      var a = arr[i], b = arr[i+segment];
      if(!b) b = arr[i];
      var alpha = 0.05 + 0.55*Math.pow(i/Math.max(1,n-1), 1.7);
      simCtx.strokeStyle = baseColor + alpha.toFixed(3) + ")";
      simCtx.lineWidth = (label === "cyan" ? 2.2 : 1.7);
      simCtx.beginPath();
      simCtx.moveTo(cx + a[kx]*scale, pivotY + a[ky]*scale);
      simCtx.lineTo(cx + b[kx]*scale, pivotY + b[ky]*scale);
      simCtx.stroke();
    }
    simCtx.restore();
  }

  function drawBob(x, y, r, light, dark){
    simCtx.save();
    var g = simCtx.createRadialGradient(x - r*0.35, y - r*0.4, r*0.15, x, y, r);
    g.addColorStop(0, light);
    g.addColorStop(0.55, light);
    g.addColorStop(1, dark);
    simCtx.fillStyle = g;
    simCtx.beginPath(); simCtx.arc(x, y, r, 0, TAU); simCtx.fill();
    simCtx.strokeStyle = "rgba(255,255,255,.35)";
    simCtx.lineWidth = 1;
    simCtx.stroke();
    simCtx.restore();
  }

  function drawDriftChart(){
    var w = driftCanvas.clientWidth, h = driftCanvas.clientHeight;
    if(!setupCanvas(driftCanvas, driftCtx) || w < 20 || h < 20) return;
    driftCtx.clearRect(0,0,w,h);

    var data = P.errorHistory;
    var left = 4, top = 6, right = w - 4, bottom = h - 8;
    driftCtx.strokeStyle = "rgba(80,110,135,.25)";
    driftCtx.lineWidth = 1;
    driftCtx.beginPath(); driftCtx.moveTo(left, (top+bottom)/2); driftCtx.lineTo(right, (top+bottom)/2); driftCtx.stroke();

    if(data.length < 2){
      driftCtx.fillStyle = "rgba(140,163,184,.7)";
      driftCtx.font = "11px system-ui, sans-serif";
      driftCtx.fillText("collecting error samples…", left+6, (top+bottom)/2 - 4);
      return;
    }

    var minV = Infinity, maxV = -Infinity;
    for(var i = 0; i < data.length; i++){
      if(data[i].e < minV) minV = data[i].e;
      if(data[i].e > maxV) maxV = data[i].e;
    }
    if(maxV < 0) maxV = 0;
    if(minV > 0) minV = 0;
    var pad = (maxV - minV) * 0.2 + 1e-12;
    var lo = minV - pad, hi = maxV + pad;
    var span = hi - lo || 1;

    var tMin = data[0].t, tMax = data[data.length-1].t;
    var tSpan = (tMax - tMin) || 1;

    driftCtx.strokeStyle = "rgba(67,233,123,.95)";
    driftCtx.lineWidth = 1.7;
    driftCtx.beginPath();
    for(var j = 0; j < data.length; j++){
      var x = left + (data[j].t - tMin)/tSpan*(right-left);
      var yv = bottom - (data[j].e - lo)/span*(bottom-top);
      if(j === 0) driftCtx.moveTo(x, yv); else driftCtx.lineTo(x, yv);
    }
    driftCtx.stroke();

    driftCtx.fillStyle = "rgba(140,163,184,.75)";
    driftCtx.font = "10px ui-monospace, monospace";
    driftCtx.fillText("±" + fmt(Math.max(Math.abs(lo), Math.abs(hi)), 4) + "%", left+4, top+10);
    ui.chartRange.textContent = "±" + fmt(Math.max(Math.abs(minV), Math.abs(maxV)), 4) + "%";
  }

  /* ---------- Lightweight DOM/integration self-check for normal loads ---------- */
  function domSelfCheck(){
    var checks = [];
    function ok(name, cond){ checks.push({name:name, ok:!!cond}); }
    ok("canvas:sim", !!sim && sim.width > 0 && sim.height > 0);
    ok("canvas:drift", !!driftCanvas);
    ok("canvas2d:sim", !!simCtx);
    ok("inputs>=3", document.querySelectorAll("input").length >= 3);
    ok("buttons:pause/reset", !!ui.pauseBtn && !!ui.resetBtn);
    ok("metrics:energy/error/trajectory", !!ui.energyValue && !!ui.errorValue && !!ui.trajectoryHud);
    var bad = checks.filter(function(c){ return !c.ok; });
    return {pass: bad.length === 0, checks: checks};
  }

  /* ---------- Optional rigorous off-screen 60 second test ---------- */
  function runOffscreenTest(){
    var p = {g:P.g, m1:P.m1, m2:P.m2, l1:P.l1, l2:P.l2, dt:P.dt};
    var state = [P.th1, 0, P.th2, 0];
    function d(s){
      var dd = s[0]-s[2], cd = Math.cos(dd), sd = Math.sin(dd);
      var den = 2*p.m1 + p.m2 - p.m2*Math.cos(2*dd);
      return [
        s[1],
        (-p.g*(2*p.m1+p.m2)*Math.sin(s[0]) - p.m2*p.g*Math.sin(s[0]-2*s[2])
          - 2*sd*p.m2*(s[3]*s[3]*p.l2 + s[1]*s[1]*p.l1*cd))/(p.l1*den),
        s[3],
        (2*sd*(s[1]*s[1]*p.l1*(p.m1+p.m2) + p.g*(p.m1+p.m2)*Math.cos(s[0])
          + s[3]*s[3]*p.l2*p.m2*cd))/(p.l2*den)
      ];
    }
    function step(st, h){
      var k1=d(st);
      var a=[st[0]+.5*h*k1[0], st[1]+.5*h*k1[1], st[2]+.5*h*k1[2], st[3]+.5*h*k1[3]];
      var k2=d(a);
      var b=[st[0]+.5*h*k2[0], st[1]+.5*h*k2[1], st[2]+.5*h*k2[2], st[3]+.5*h*k2[3]];
      var k3=d(b);
      var c=[st[0]+h*k3[0], st[1]+h*k3[1], st[2]+h*k3[2], st[3]+h*k3[3]];
      var k4=d(c);
      return [st[0]+h/6*(k1[0]+2*k2[0]+2*k3[0]+k4[0]),
              st[1]+h/6*(k1[1]+2*k2[1]+2*k3[1]+k4[1]),
              st[2]+h/6*(k1[2]+2*k2[2]+2*k3[2]+k4[2]),
              st[3]+h/6*(k1[3]+2*k2[3]+2*k3[3]+k4[3])];
    }
    function energy(s){
      var T = .5*p.m1*p.l1*p.l1*s[1]*s[1]
            + .5*p.m2*(p.l1*p.l1*s[1]*s[1] + p.l2*p.l2*s[3]*s[3]
                       + 2*p.l1*p.l2*s[1]*s[3]*Math.cos(s[0]-s[2]));
      var V = -(p.m1+p.m2)*p.g*p.l1*Math.cos(s[0]) - p.m2*p.g*p.l2*Math.cos(s[2]);
      return T + V;
    }
    var t0 = performance.now();
    var E0 = energy(state);
    var steps = Math.ceil(60/p.dt);
    var maxAbs = 0, maxAbsPct = 0;
    for(var i=0;i<steps;i++){
      state = step(state, p.dt);
      if((i & 127) === 0){
        var err = (energy(state)-E0)/Math.abs(E0)*100;
        var a = Math.abs(err);
        if(a > maxAbs) { maxAbs = a; maxAbsPct = err; }
      }
    }
    var elapsed = performance.now()-t0;
    return {
      simulatedSeconds: 60,
      rk4Steps: steps,
      maxAbsRelativeEnergyDriftPct: maxAbs,
      worstSignedPct: maxAbsPct,
      thresholdPct: 0.25,
      stableForOneMinute: maxAbs < 0.25,
      wallMs: Math.round(elapsed),
      dom: domSelfCheck().checks
    };
  }

  /* ---------- Boot ---------- */
  function boot(){
    syncInputs();
    resetState();
    setRunning(true);
    var dom = domSelfCheck();
    ui.selfTestBadge.textContent = dom.pass ? "pass" : "fail";
    ui.selfTestBadge.style.color = dom.pass ? "#43e97b" : "#ff5f6d";
    requestAnimationFrame(function(now){
      P.lastFrame = now;
      requestAnimationFrame(frame);
    });

    /* Query flag ?selftest=1 lets a headless browser verify physics and DOM. */
    if((new URLSearchParams(location.search)).has("selftest")){
      window.setTimeout(function(){
        try{
          var report = runOffscreenTest();
          report.overall = report.stableForOneMinute && dom.pass;
          var pre = document.createElement("pre");
          pre.id = "selftest-result";
          pre.setAttribute("data-result", report.overall ? "pass" : "fail");
          pre.textContent = JSON.stringify(report, null, 2);
          document.body.appendChild(pre);
        }catch(err){
          var pre2 = document.createElement("pre");
          pre2.id = "selftest-result";
          pre2.setAttribute("data-result", "fail");
          pre2.textContent = "SELFTEST EXCEPTION: " + err.message;
          document.body.appendChild(pre2);
        }
      }, 350);
    }
  }

  if(document.readyState === "loading"){
    document.addEventListener("DOMContentLoaded", boot);
  }else{
    boot();
  }
})();
</script>
</body>
</html>
