function getJSON(url){return new Promise((res,rej)=>{http.get(url,r=>{let d='';r.on('data',c=>d+=c);r.on('end',()=>res(JSON.parse(d)));}).on('error',rej)});}
(async()=>{
  const tabs = await getJSON('http://127.0.0.1:9223/json/list');
  const tab = tabs.find(t=>t.type==='page');
  const ws = new WebSocket(tab.webSocketDebuggerUrl);
  let id=0; const pending=new Map();
  ws.onmessage = e=>{const m=JSON.parse(e.data); if(m.id&&pending.has(m.id)){pending.get(m.id)(m); pending.delete(m.id);}};
  await new Promise(r=>ws.onopen=r);
  function send(method,params={}){return new Promise(res=>{const i=++id;pending.set(i,res);ws.send(JSON.stringify({id:i,method,params}));});}
  await send('Runtime.enable');
  await send('Emulation.setDeviceMetricsOverride',{width:1280,height:720,deviceScaleFactor:1,mobile:false});
  await new Promise(r=>setTimeout(r,1500));
  const expr = `(()=>{
    const r=id=>{const e=document.getElementById(id),b=e.getBoundingClientRect();return {x:Math.round(b.x),y:Math.round(b.y),w:Math.round(b.width),h:Math.round(b.height),sh:e.scrollHeight,ch:e.clientHeight};};
    const aside=document.querySelector('aside'), b=aside.getBoundingClientRect();
    const canvasCard=document.querySelector('.canvas-card').getBoundingClientRect();
    const readout=document.querySelector('.readout-row').getBoundingClientRect();
    const footer=document.querySelector('footer').getBoundingClientRect();
    return {
      viewport:[innerWidth,innerHeight],
      body:{sw:document.body.scrollWidth,sh:document.body.scrollHeight,cw:document.body.clientWidth,ch:document.body.clientHeight},
      app:r('app'), aside:{x:Math.round(b.x),y:Math.round(b.y),w:Math.round(b.width),h:Math.round(b.height),sh:aside.scrollHeight,ch:aside.clientHeight},
      canvasCard:{x:Math.round(canvasCard.x),y:Math.round(canvasCard.y),w:Math.round(canvasCard.width),h:Math.round(canvasCard.height)},
      readout:{x:Math.round(readout.x),y:Math.round(readout.y),w:Math.round(readout.width),h:Math.round(readout.height)},
      footer:{y:Math.round(footer.y),h:Math.round(footer.height)},
      simCanvas:r('sim'), drift:r('driftChart'),
      energy:document.getElementById('energyValue').textContent,
      error:document.getElementById('errorValue').textContent,
      time:document.getElementById('simTimeBadge').textContent,
      steps:document.getElementById('stepCount').textContent,
      trail:document.getElementById('trailCount').textContent
    };
  })()`;
  const res = await send('Runtime.evaluate',{expression:expr,returnByValue:true});
  if(res.result.exceptionDetails) console.log('EXC',JSON.stringify(res.result.exceptionDetails,null,2));
  console.log(JSON.stringify(res.result.result.value,null,2));
  ws.close();
})();
